def day_span(start, end):
    days, d = ([], start.date())
    while d <= end.date() and len(days) < 60:
        days.append(d)
        d += _dt.timedelta(days=1)
    return days

PROD_DAY_START_H = 8

SLOT_MIN = 10

SLOTS_PER_DAY = 24 * 60 // SLOT_MIN

SHIFT_WINDOWS = {'day': (0, 480), 'swing': (480, 960), 'night': (720, 1200), 'graveyard': (960, 1440), 'fixed': (0, 540)}

MEAL_BREAKS = {'day': (240, 270), 'swing': (720, 750), 'night': (960, 990), 'graveyard': (1200, 1230), 'fixed': (240, 300)}

REGION_SHIFTS = {'ZC': ('day', 'swing'), 'ZAB': ('day', 'swing')}

_AREA2REGION = {'ZC': 'ZC', 'ZA': 'ZAB', 'ZB': 'ZAB'}

def production_day(dt):
    d = dt.date()
    return d - _dt.timedelta(days=1) if dt.hour < PROD_DAY_START_H else d

def _slot_of(dt):
    pd = production_day(dt)
    anchor = _dt.datetime.combine(pd, _dt.time(PROD_DAY_START_H))
    return (pd, int((dt - anchor).total_seconds() // 60) // SLOT_MIN)

def slot_spans(start, end):
    out = {}
    pd, i0 = _slot_of(start)
    _pd_end, _i_end = _slot_of(end)
    cur_day, cur_slot = (pd, i0)
    guard = 0
    while guard < 60 * SLOTS_PER_DAY:
        out.setdefault(cur_day, set()).add(cur_slot)
        if (cur_day, cur_slot) == (_pd_end, _i_end):
            break
        cur_slot += 1
        if cur_slot >= SLOTS_PER_DAY:
            cur_slot, cur_day = (0, cur_day + _dt.timedelta(days=1))
        guard += 1
    return out

def slots_to_hex(slots):
    n = 0
    for i in slots:
        if 0 <= i < SLOTS_PER_DAY:
            n |= 1 << i
    return format(n, '036x')

def hex_to_slots(h):
    n = int(h, 16)
    return [i for i in range(SLOTS_PER_DAY) if n >> i & 1]

def window_slots(name):
    a, b = SHIFT_WINDOWS[name]
    return {i for i in range(a // SLOT_MIN, min(b + SLOT_MIN - 1, 24 * 60) // SLOT_MIN) if i < SLOTS_PER_DAY}

def planned_slots(region):
    out = set()
    for sh in REGION_SHIFTS[region]:
        out |= window_slots(sh)
    return out

def overtime_slots(region, slots):
    return sorted(set(slots) - planned_slots(region))

def kun_region(kun_id):
    for k, area, _n, _e in KUN_ROSTER:
        if k == kun_id:
            return _AREA2REGION[area]
    return None
